const pad2 = (n: number) => String(n).padStart(2, '0');

/** Задать время «HH:MM» и включить/выключить напоминание молитвы. При включении — «התזכורת פעילה ומוצגת במסך הבית.». */
export async function setPrayerReminder(p: PrayerName, hh: number | string, mm: number | string, on: boolean) {
  for (const [label, v] of [['שעות', hh], ['דקות', mm]] as const) {
    const f = await byLabel(label);
    await f.clearValue().catch(() => {});
    await f.setValue(typeof v === 'number' ? pad2(v) : v);
  }
  if (await driver.isKeyboardShown().catch(() => false)) await driver.hideKeyboard().catch(() => {});
  const sw = await byLabel(`תזכורת ל${p}`);
  if ((await isOn(sw)) !== on) await sw.click();
  await driver.waitUntil(async () => (await isOn(await byLabel(`תזכורת ל${p}`))) === on, { timeout: 10000, timeoutMsg: `switch «תזכורת ל${p}» не стал ${on}` });
  if (on) await expect(byTextContains(REMINDER_ACTIVE)).toBeDisplayed({ wait: 10000 });
}

/** Время устройства (локальное) — часы и минуты. Запасной путь — часы компьютера. */
export async function deviceClock(): Promise<{ h: number; m: number }> {
  try {
    const s = String(await driver.execute('mobile: getDeviceTime', { format: 'HH:mm' }));
    const m = s.match(/(\d{1,2}):(\d{2})/);
    if (m) return { h: Number(m[1]), m: Number(m[2]) };
  } catch { /* нет команды — ниже */ }
  const d = new Date();
  return { h: d.getHours(), m: d.getMinutes() };
}
/** Сдвиг времени на n минут (через полночь — по модулю суток). */
export function shiftClock(c: { h: number; m: number }, n: number) {
  const t = (((c.h * 60 + c.m + n) % 1440) + 1440) % 1440;
  return { h: Math.floor(t / 60), m: t % 60 };
}
export const hhmm = (c: { h: number; m: number }) => `${pad2(c.h)}:${pad2(c.m)}`;

