/** Уведомление «<молитва> / תזכורת יומית בשעה HH:MM» от «אור הגאולה» в центре уведомлений.
 *  iOS 13.10: label «אור הגאולה, …, שחרית, תזכורת יומית בשעה 14:59». Элементы принадлежат SpringBoard — на время поиска
 *  defaultActiveApplication = com.apple.springboard. TODO калибровка: на англ./рус. устройстве имя приложения то же (иврит). */
export async function findPrayerNotification(p: PrayerName, time: string): Promise<string | null> {
  const body = `תזכורת יומית בשעה ${time}`;
  if (driver.isIOS) await driver.updateSettings({ defaultActiveApplication: 'com.apple.springboard' }).catch(() => {});
  try {
    const els = driver.isAndroid
      ? await $$(`android=new UiSelector().textContains("${body}")`).getElements()
      : await $$(`-ios predicate string:label CONTAINS "אור הגאולה" AND label CONTAINS "${p}" AND label CONTAINS "${body}"`).getElements();
    for (const el of els) {
      const t = driver.isAndroid ? await el.getText().catch(() => '') : await labelOf(el);
      if (t) return t;
    }
    return null;
  } finally {
    if (driver.isIOS) await driver.updateSettings({ defaultActiveApplication: 'auto' }).catch(() => {});
  }
}

/** Ждать уведомление до `deadlineMs` (каждые 20 с открывать центр уведомлений). Возвращает label или null. */
export async function waitPrayerNotification(p: PrayerName, time: string, deadlineMs: number): Promise<string | null> {
  const until = Date.now() + deadlineMs;
  while (Date.now() < until) {
    await openNotificationCenter();
    const hit = await findPrayerNotification(p, time);
    if (hit) return hit;
    await closeNotificationCenter();
    await driver.pause(20000);
  }
  await openNotificationCenter();
  return findPrayerNotification(p, time);
}

/** Закрыть центр уведомлений и вернуть приложение на передний план. */
export async function closeNotificationCenter() {
  if (driver.isAndroid) await driver.back().catch(() => {});
  else await driver.execute('mobile: pressButton', { name: 'home' }).catch(() => {});
  await driver.pause(800);
}
export async function returnToApp() {
  await closeNotificationCenter();
  if (appId()) await driver.activateApp(appId());
  await (await byText('בית')).waitForDisplayed({ timeout: 30000 });
}

