/** Еврейская дата в заголовке главной: «ג׳ חשון תשפ״ז» (день, месяц — возможно «אדר ב׳», год). */
const HEB_HEADER_RE = '[א-ת]+[׳״][א-ת]? [א-ת]+( [אב]׳)? ת[א-ת]+״[א-ת]';
export type HebDate = { full: string; day: string; month: string; year: string };

export function parseHebDate(full: string): HebDate {
  const parts = full.trim().split(/\s+/);
  return { full: full.trim(), day: parts[0], month: parts.slice(1, -1).join(' '), year: parts[parts.length - 1] };
}

/** Прочитать еврейскую дату заголовка главной (самый верхний подходящий текст). */
export async function homeHebrewDate(): Promise<HebDate> {
  await toHome();
  await (await byLabel('התחל תפילה')).waitForDisplayed({ timeout: 20000 });
  const els = driver.isAndroid
    ? await $$(`android=new UiSelector().textMatches("${HEB_HEADER_RE}")`).getElements()
    : await $$(`-ios predicate string:type == "XCUIElementTypeStaticText" AND (label MATCHES "${HEB_HEADER_RE}" OR value MATCHES "${HEB_HEADER_RE}")`).getElements();
  let best = '', bestY = Infinity;
  for (const el of els) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const { y } = await el.getLocation();
    const t = (await el.getText().catch(() => '')) || (await labelOf(el));
    if (t && y < bestY) { bestY = y; best = t; }
  }
  if (!best) throw new Error('Еврейская дата в заголовке главной не найдена (ожидалось вида «ג׳ חשון תשפ״ז»)');
  return parseHebDate(best);
}

