/** Бейдж карточки: тексты месяца и дня на уровне кнопки правки (±90 pt/px по вертикали).
 *  TODO калибровка: если бейдж — склеенная подпись контейнера, искать «חשון, ג׳» в label контейнера. */
export async function badgeHasDayMonth(name: string, day: string, month: string): Promise<boolean> {
  const card = await rectOf(await scrollToDateCard(name));
  const near = async (text: string) => {
    const els = driver.isAndroid
      ? await $$(`android=new UiSelector().text("${text}")`).getElements()
      : await $$(`-ios predicate string:label == "${text}" OR value == "${text}"`).getElements();
    for (const el of els) {
      if (!(await el.isDisplayed().catch(() => false))) continue;
      const r = await rectOf(el);
      if (Math.abs(r.y + r.height / 2 - (card.y + card.height / 2)) <= 90) return true;
    }
    return false;
  };
  if ((await near(month)) && (await near(day))) return true;
  // запасной путь — склеенная подпись карточки (iOS: «חשון, ג׳, <имя>…»)
  const combined = driver.isAndroid
    ? await $(`android=new UiSelector().descriptionContains("${name}").descriptionContains("${month}")`)
    : await $(`-ios predicate string:label CONTAINS "${name}" AND label CONTAINS "${month}" AND label CONTAINS "${day}" AND NOT (label ENDSWITH "פתיחה לעריכה")`);
  return shown(combined);
}

/** Удалить запись: правка → «מחיקת התאריך» → «מחיקה». true — запись исчезла.
 *  На iOS сборки 19 удаление не работает (#9bc6265b) — тогда закрыть окно «סגירה» ЭЛЕМЕНТОМ (окно заходит под строку статуса, #36a75b77) и вернуть false. */
export async function tryDeleteDate(name: string): Promise<boolean> {
  await toHome();
  await homeDates();
  const edit = await byLabel(`${name}: פתיחה לעריכה`);
  for (let i = 0; i < 6 && !(await edit.isDisplayed().catch(() => false)); i++) await swipeUp();
  if (!(await edit.isDisplayed().catch(() => false))) return true;   // записи уже нет
  await edit.click();
  await (await byText('עריכת תאריך')).waitForDisplayed({ timeout: 15000 }).catch(() => {});
  const del = await byText('מחיקת התאריך');
  for (let i = 0; i < 4 && !(await del.isDisplayed().catch(() => false)); i++) await swipeUp();
  if (await del.isDisplayed().catch(() => false)) {
    await del.click();
    const confirm = await byText('מחיקה');
    if (await confirm.waitForDisplayed({ timeout: 8000 }).then(() => true, () => false)) await confirm.click();
  }
  const gone = await driver.waitUntil(async () => !(await shown(byLabel(`${name}: פתיחה לעריכה`))), { timeout: 10000 })
    .then(() => true, () => false);
  if (!gone) {
    const close = await $('~סגירה');
    if (await close.isExisting().catch(() => false)) await close.click().catch(() => {});
  }
  return gone;
}

